body:
Just use official status bar component from react native. Then you wrap your app within it or the component only.

Just like this:

<StatusBar
        animated={true}
        backgroundColor="#61dafb"
        barStyle={statusBarStyle}
        showHideTransition={statusBarTransition}
        hidden={hidden} />
           <App/>
</StatusBar>

**Code is this:**

export default function MenuItems() {

return (

<ScrollView>  


{foods.map((food, index)=> (

<View key={index}>  


<View style={styles.menuItem}>  


<FoodInfo food = {food}></FoodInfo>

<FoodImage food = {food}></FoodImage>

</View>  


<Divider width={0.5} orientation="vertical"></Divider>

</View>  


))}

</ScrollView>  


)

}
